<!--
  GearSwap Atelier · the optimizer's page of a set (optpage.ts): its line on top, what is looked for on the left, the
  result on the right. The controls keep the attributes the old page's handlers read (opt_page.js, optimizer.js,
  events.js).

  @file    atelier/src/screens/optimizer/OptPage.svelte
  @author  ejouanchicot
-->
<script lang="ts">
  import OptBlocks from './OptBlocks.svelte';
  import StatPage from './StatPage.svelte';
  import {selSync} from '../../components/selsync';
  import type {OptPageView, Param, Visual} from './optpage';

  let {view}: {view: OptPageView} = $props();
</script>

{#snippet param(p: Param)}{#if p.k === 'spells'}<label class="opf">{p.label} <select class="buffsel" multiple size="6" data-nukespells={p.key} use:selSync={p.options.filter(o => o.selected).map(o => o.value)}>{#each p.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.value}</option>{/each}</select></label>{:else if p.k === 'tp'}<label class="opf">{p.label} <input type="number" class="tpin" step="250" min="1000" max="3000" value={p.value}></label>{:else if p.k === 'number'}<label class="opf">{p.label} <input type="number" step={p.step} min="1000" max="3000" data-optopt={p.opt} value={p.value}>{p.tail}</label>{:else if p.k === 'select'}<label class="opf">{p.label} <select class="buffsel" {...{[p.attr]: p.attrValue}} use:selSync={(p.options.find(o => o.selected) || {value: undefined}).value}>{#each p.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.label}</option>{/each}</select></label>{:else if p.k === 'check'}<label class="opf"><input type="checkbox" data-optopt={p.opt} checked={p.checked}> {p.label}</label>{:else}<span class="kwarn">{p.text}</span>{/if}{/snippet}
{#snippet visual(v: Visual)}{#if v.k === 'rows'}<div class="cycparts">{#each v.rows as r, i (i)}<div class="cycrow"><span>{r.label}</span><div class="cycbar {r.tall ? 'tall' : ''} {r.round !== undefined ? 'gauge' : ''}" style={r.round !== undefined ? `--round:${r.round}%` : undefined}>{#each r.parts as x, j (j)}<i class={x.cls} style="width:{x.width}%" title={x.title}>{#if x.text}<b>{x.text}</b>{/if}</i>{/each}</div><span class="num">{r.num}</span></div>{/each}{#if v.note || v.legend.length}<p class="cyclegend">{#if v.note}<span class="muted">{v.note}</span>{/if}{#each v.legend as l, i (i)}<span><i class={l.cls}></i>{l.text}</span>{/each}</p>{/if}</div>{:else if v.k === 'factors'}<table class="opfac"><tbody>{#each v.rows as f, i (i)}<tr><th>{f.label}</th>{#if v.was}<td>{f.a}</td>{/if}<td>{f.b}</td>{#if v.was}<td class="facbar"><span class="mid"></span><i class={f.up ? 'up' : 'down'} style="width:{f.width}%;{f.up ? 'left:50%' : 'right:50%'}"></i></td><td class={f.up ? 'up' : 'down'}>{f.pct}</td>{/if}</tr>{/each}</tbody></table>{:else}<div class="opcurve"><svg viewBox="0 0 {v.W} {v.H}" role="img" aria-label={v.label}>{#if v.band}<rect class="band" x={v.band.x} y="6" width={v.band.w} height={v.H - 24}/>{:else if v.mark}<line class="mark" x1={v.mark.x} x2={v.mark.x} y1="6" y2={v.H - 18}/>{/if}{#if v.was}<polyline class="was" points={v.was}/>{/if}<polyline class="now" points={v.now}/>{#each v.ticks as tk (tk.v)}<text x={tk.x} y={v.H - 4}>{tk.v}</text>{/each}</svg><p class="cyclegend"><span class="muted">{v.label}</span>{#each v.legend as l, i (i)}<span><i class={l.cls}></i>{l.text}</span>{/each}</p></div>{/if}{/snippet}

<article class="detail oppage"><header class="ophead"><button class="btn ghost" data-optback title={view.head.backTitle}>{view.head.back}</button><h2 class="display">{view.head.title}</h2><span class="opset">{view.head.set}</span><span class="muted small">{view.head.ctx}</span><span class="sp"></span><div class="opgo">{@html view.head.goHtml}</div></header>{#if view.noEngine !== null}<p class="tpnote">{view.noEngine}</p>{:else}<div class="opcols"><section class="opcol">{#if view.statWhat}<StatPage what={view.statWhat} />{:else if view.what}{@const w = view.what}{#if w.top.k === 'nuke'}{@const nk = w.top}<h3 class="ophd">{nk.title}</h3><div class="opparams"><label class="opf">{nk.sit.label + ' '}<select class="buffsel" data-optopt="nukeSit" use:selSync={(nk.sit.options.find(o => o.selected) || {value: undefined}).value}>{#each nk.sit.options as op (op.value)}<option value={op.value} selected={op.selected}>{op.label}</option>{/each}</select></label></div>{#each nk.lines as ln, i (i)}{#if ln.k === 'p'}<p class="oplocks">{ln.text}</p>{:else}<label class="opf"><input type="checkbox" data-optopt="nukeMpLow" checked={ln.checked}>{' ' + ln.label}</label>{/if}{/each}{:else}<OptBlocks limits={w.top.limits} />{/if}<h3 class="ophd">{w.title} {@html w.helpBtnHtml}</h3>{#if w.help}<p class="wshelp">{w.help}</p>{/if}<div class="opobjs" role="radiogroup">{#each w.objs as o (o.v)}{#if o.disabled}<button class="opobj {o.on ? 'on' : ''}" role="radio" aria-checked={o.on} data-objtip={o.tip} disabled><b>{o.label}</b><span>{o.desc}</span></button>{:else}<button class="opobj {o.on ? 'on' : ''}" role="radio" aria-checked={o.on} data-objtip={o.tip} data-optobj={o.key} data-v={o.v}><b>{o.label}</b><span>{o.desc}</span></button>{/if}{/each}</div>{#if w.params.length}<div class="opparams">{#each w.params as p, i (i)}{@render param(p)}{/each}</div>{/if}<OptBlocks search={w.search} />{/if}</section><section class="opcol">{#if view.statResult}<StatPage result={view.statResult} />{:else if view.result}{@const r = view.result}<h3 class="ophd">{r.title}</h3>{#if r.none !== null}<p class="tpnote">{r.none}</p>{:else}{#if r.big}<div class="opbig"><div><span class="muted small">{r.big.label}</span><div class="opval"><b>{r.big.value}</b>{#if r.big.diff}<em class={r.big.diff.up ? 'up' : 'down'}>{r.big.diff.text}</em>{/if}</div>{#if r.big.was}<span class="muted small">{r.big.was}</span>{/if}</div>{#if r.big.verdict}<span class="opverdict {r.big.verdict.cls}">{r.big.verdict.text}</span>{/if}</div>{/if}{#if r.visual}{@render visual(r.visual)}{/if}<div class="opres"><table class="rdvs optable"><thead><tr><th></th>{#each r.heads as h, i (i)}<th>{h}</th>{/each}</tr></thead><tbody>{#each r.rows as row, i (i)}<tr class={row.obj ? 'obj' : ''}><th>{row.label}</th>{#each row.cells as c, j (j)}{#if c}<td class="{c.better ? 'better' : ''} {c.short ? 'short' : ''}">{c.text}</td>{:else}<td>—</td>{/if}{/each}</tr>{/each}</tbody></table><div class="opside"><OptBlocks changes={r.changes} /></div></div>{#if r.trialHtml}{@html r.trialHtml}{:else}<p class="muted small">{r.noTry}</p>{/if}{#if r.notes}<p class="kwarn">{r.notes}</p>{/if}{@html r.calcHtml}{/if}{/if}</section></div>{/if}</article>
